={{ {
  model: "my-free-tier",
  messages: [
    {
      role: "system",
      content: "You are a Firecrawl research agent. Given a solution domain, search for and extract the best enterprise content from industry leaders. Return structured research data."
    },
    {
      role: "user",
      content: `Research the following MEAICON solution domain: {{ $json.domain }}

Find content from these competitor/reference sites:
{{ $json.competitors }}

Extract:
1. Technical architecture details
2. Service capabilities
3. Industry best practices
4. Key differentiators
5. Customer value propositions

Return as structured JSON with sections: overview, architecture, capabilities, differentiators, use-cases, technical-specs.}
      }
    ],
    temperature: 0.3,
    max_tokens: 4000
} }}

={{ {
  model: "my-free-tier",
  messages: [
    {
      role: "system",
      content: "You are a LangChain content enhancement agent. Transform raw research into MEAICON-branded, enterprise-grade content for a solution page. Follow MEAICON voice: professional, technical, MEA-region focused, outcome-oriented. Output must be valid Nunjucks/Markdown content ready for template injection."
    },
    {
      role: "user",
      content: `Transform this research into enhanced content for MEAICON page: {{ $json.page }}

Research Data:
{{ $json.research }}

MEAICON Context:
- Company: MEAICON LLC FZ, Meydan Free Zone, Dubai, UAE
- Region: Middle East & Africa (MEA)
- Services: Connectivity, Data Centre, Cyber Security, Blockchain, Consulting
- Voice: Professional, authoritative, technically precise, outcome-focused

Requirements:
1. 1,500-3,000 words
2. Include: Overview, Technical Architecture, Capabilities, Differentiators, Use Cases, MEA Relevance
3. Use MEAICON branding (not competitor names)
4. Include specific technical details (not marketing fluff)
5. Reference MEA region specifics (UAE, KSA, Egypt, Kenya, etc.)
6. Output as Markdown with proper H2/H3 structure
7. Include solution icon reference

Return ONLY the enhanced content markdown.}
      }
    ],
    temperature: 0.4,
    max_tokens: 6000
} }}

={{ {
  model: "my-free-tier",
  messages: [
    {
      role: "system",
      content: "You are a fact-checking agent. Verify all technical claims in the enhanced content. Flag any hallucinations or unverifiable claims. Return a JSON report with: verified_claims[], flagged_claims[], confidence_score (0-1)."
    },
    {
      role: "user",
      content: `Fact-check this enhanced content for MEAICON page: {{ $json.page }}

Content:
{{ $json.enhanced_content }}

Verify:
- Technical specifications (throughput, latency, standards)
- MEA region claims (presence, regulations, partnerships)
- Industry standards references (IEEE, ISO, ITU, etc.)
- Competitor claims (should be rebranded to generic)

Return JSON report.}
      }
    ],
    temperature: 0.1,
    max_tokens: 3000
} }}

parameters.functionCode:
const fs = require('fs');
const path = require('path');

const page = $json.page;
const enhancedContent = $json.enhanced_content;
const factCheck = $json.fact_check;

// Save enhanced content to research-data/langchain/<domain>/enhanced-content.md
const domain = page.replace('.njk', '').replace('pages/solutions/', '').replace('pages/industries/', 'industries/').replace('pages/case-studies/', 'case-studies/').replace('pages/insights/', 'insights/').replace('pages/', '');
const outputDir = path.join(__dirname, '..', 'research-data', 'langchain', domain);

if (!fs.existsSync(outputDir)) {
  fs.mkdirSync(outputDir, { recursive: true });
}

fs.writeFileSync(path.join(outputDir, 'enhanced-content.md'), enhancedContent);
fs.writeFileSync(path.join(outputDir, 'fact-checks.json'), JSON.stringify(factCheck, null, 2));
fs.writeFileSync(path.join(outputDir, 'summary.md'), `# ${page} Enhancement Summary

Fact Check Confidence: ${factCheck.confidence_score}
Verified Claims: ${factCheck.verified_claims?.length || 0}
Flagged Claims: ${factCheck.flagged_claims?.length || 0}
`);

return [{ json: { success: true, page, outputDir } }];

// Inject enhanced content into Nunjucks template
const { execSync } = require('child_process');
const path = require('path');

const pages = $json.pages || [$json.page];
const results = [];

for (const page of pages) {
  try {
    const scriptPath = path.join(__dirname, '..', 'scripts', 'inject-enhanced-content.py');
    // Modify the injection map for this specific page
    const domain = page.replace('.njk', '').replace('pages/solutions/', '').replace('pages/industries/', 'industries/').replace('pages/case-studies/', 'case-studies/').replace('pages/insights/', 'insights/').replace('pages/', '');
    const enhancedPath = path.join(__dirname, '..', 'research-data', 'langchain', domain, 'enhanced-content.md');
    const templatePath = path.join(__dirname, '..', 'pages', page);

    if (require('fs').existsSync(enhancedPath) && require('fs').existsSync(templatePath)) {
      // Use the existing injection script logic
      const template = require('fs').readFileSync(templatePath, 'utf8');
      const enhanced = require('fs').readFileSync(enhancedPath, 'utf8');

      let updated;
      if (template.includes('</main>')) {
        updated = template.replace('</main>', enhanced + '\n\n</main>');
      } else {
        updated = template + '\n\n' + enhanced;
      }

      require('fs').writeFileSync(templatePath, updated);
      results.push({ page, success: true });
    } else {
      results.push({ page, success: false, error: 'Missing enhanced content or template' });
    }
  } catch (error) {
    results.push({ page, success: false, error: error.message });
  }
}

return [{ json: { results } }];

// Run validation and build
const { execSync } = require('child_process');
const path = require('path');

try {
  // Build
  execSync('npm run build', { cwd: path.join(__dirname, '..'), stdio: 'pipe' });

  // Audit metadata
  execSync('npm run audit:metadata', { cwd: path.join(__dirname, '..'), stdio: 'pipe' });

  // Validate content
  execSync('npm run validate:content', { cwd: path.join(__dirname, '..'), stdio: 'pipe' });

  return [{ json: { success: true, message: 'Build and validation passed' } }];
} catch (error) {
  return [{ json: { success: false, error: error.message, stdout: error.stdout?.toString(), stderr: error.stderr?.toString() } }];
}
